SELECT ct.id AS contact_id, ct.manually_created AS "contact_manually_created!", co.id AS "company_id?", COALESCE(co.email_sync, TRUE) AS "email_sync!", COALESCE(co.manually_created, FALSE) AS "company_manually_created!" FROM crm_contacts ct LEFT JOIN crm_companies co ON co.id = ct.company_id WHERE ct.team_id = $1 AND LOWER(ct.email) = $2 AND ( -- Company-less contacts are the personal-email ones -- email sync files on their own. $4 OR ct.company_id IS NULL OR EXISTS ( SELECT 1 FROM crm_domains d WHERE d.company_id = ct.company_id AND LOWER(d.domain) = $3 ) ) AND (NOT $4 OR (SELECT COUNT(*) FROM crm_contacts other WHERE other.team_id = $1 AND LOWER(other.email) = $2) = 1) ORDER BY ct.company_id IS NULL, ct.id LIMIT 1
